(7513283, 1199805, 96751, '<td valign="top">Awwwww, such lovely light.</td>', 'Awwwww, such lovely light.', '2017-05-12 02:22:19.000000', NULL, 1),
(7513284, 1199412, 96751, '<td valign="top">There is something so cruel and lonely about this image. And it''s composition reminds me a bit of Da Vinci''s evolution of man.  The lines, and the diminishing scale of this from left to right is brilliant.</td>', 'There is something so cruel and lonely about this image. And it''s composition reminds me a bit of Da Vinci''s evolution of man.  The lines, and the diminishing scale of this from left to right is brilliant.', '2017-05-12 02:23:28.000000', NULL, 1),
(7513285, 1199519, 96751, '<td valign="top">A beautiful shot, but the people and pet seem so incidental. Even the little berries in the foreground are more prominent.</td>', 'A beautiful shot, but the people and pet seem so incidental. Even the little berries in the foreground are more prominent.', '2017-05-12 02:25:29.000000', NULL, 1),
